#!/bin/bash
set -e
echo "Installing files..."
mkdir -p app components hooks

python3 -c '
import base64, os
os.makedirs(os.path.dirname("app/globals.css") if os.path.dirname("app/globals.css") else ".", exist_ok=True)
open("app/globals.css", "w").write(__import__("base64").b64decode("").decode())
print("✓ app/globals.css")
'

